import path from "path";
import os from "os";
import zlib from "zlib";

const dayStart = new Date("2026-11-09T00:00:00+08:00").getTime();
const dayEnd = dayStart + 864e5;
const base = path.join(os.homedir(), ".dsh", "sessions");
const files = [];
(function walk(p) {
  for (const e of fs.readdirSync(p, { withFileTypes: true })) {
    const fp = path.join(p, e.name);
    if (e.isDirectory()) walk(fp);
    else if (/\.jsonl\.zstd$/.test(e.name)) {
      const st = fs.statSync(fp);
      if (st.mtimeMs >= dayStart && st.mtimeMs < dayEnd) files.push(fp);
    }
  }
})(base);

const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
function dec(buf) {
  const idx = [];
  for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idx.push(i);
  if (idx.length <= 1) { try { return zlib.zstdDecompressSync(buf).toString("utf8"); } catch { return buf.toString("utf8"); } }
  let o = "";
  for (let k = 0; k < idx.length; k++) {
    const s = idx[k], e = k + 1 < idx.length ? idx[k + 1] : buf.length;
    try { o += zlib.zstdDecompressSync(buf.subarray(s, e)).toString("utf8"); } catch {}
  }
  return o;
}
const KEY = /finish_reason|finishReason|finish reason|Provider finish/i;
const modelOf = {}, hits = [], samples = [];

for (const fp of files) {
  const sid = path.basename(path.dirname(fp)).replace(/^session-/, "").slice(0, 8);
  const raw = dec(fs.readFileSync(fp));
  const lines = raw.split("\n").filter(Boolean);
  let model = "?", provider = "?", maxStep = 0, nCalls = 0;
  const evs = [];
  for (const l of lines) {
    try { evs.push(JSON.parse(l)); } catch { /* skip */ }
  }
  for (const e of evs) {
    if (e.type === "request/header") {
      const c = (e.data && e.data.header && e.data.header.config) || {};
      if (c.model) model = c.model;
      if (c.provider) provider = c.provider;
    }
    if (e.type === "tool/call") nCalls++;
    const s = e.step || (e.data && e.data.step);
    if (typeof s === "number" && s > maxStep) maxStep = s;
  }
  if (model === "?") {
    for (const e of evs.slice(0, 4)) {
      const t = JSON.stringify(e.data || e);
      const m = t.match(/powered by the ([^"\\]+?) model/);
      if (m) { model = m[1]; break; }
    }
  }
  modelOf[sid] = { model, provider, maxStep, nCalls, hits: 0 };
  for (const l of lines) {
    if (!KEY.test(l)) continue;
    hits.push(sid);
    modelOf[sid].hits++;
    if (samples.length < 14) {
      let type = "?";
      try { type = JSON.parse(l).type || "?"; } catch {}
      const i = l.search(KEY);
      samples.push({ sid, type, model, provider, text: l.slice(Math.max(0, i - 120), i + 220).replace(/\s+/g, " ") });
    }
  }
}

console.log("=== 今日会话模型/provider 分布 ===");
const byModel = {};
for (const [sid, v] of Object.entries(modelOf)) {
  const k = v.provider + " / " + v.model;
  byModel[k] = byModel[k] || { sessions: 0, hitSessions: 0, hits: 0, steps: 0 };
  byModel[k].sessions++;
  if (v.hits > 0) byModel[k].hitSessions++;
  byModel[k].hits += v.hits;
  byModel[k].steps += v.maxStep;
}
Object.entries(byModel).sort((a, b) => b[1].hits - a[1].hits).forEach(([k, v]) =>
  console.log(String(v.sessions).padStart(3) + " 会话  " + String(v.hitSessions).padStart(3) + " 命中  " + String(v.hits).padStart(4) + " 次  " + k));

console.log("\n=== 出现 finish_reason 的会话（按次数降序）===");
Object.entries(modelOf).filter(([, v]) => v.hits > 0).sort((a, b) => b[1].hits - a[1].hits)
  .forEach(([sid, v]) => console.log(sid, String(v.hits).padStart(4) + " 次", "maxStep=" + v.maxStep, "calls=" + v.nCalls, v.provider + "/" + v.model));

console.log("\n=== 命中样本（最多 14 条，截断）===");
samples.forEach(s => console.log(s.sid, s.type, s.provider + "/" + s.model, "|", s.text));
console.log("\n会话文件数=" + files.length, "命中行总数=" + hits.length);

