import fs from "fs";
import path from "path";
import os from "os";
import zlib from "zlib";

const TZ = 8 * 3600 * 1000;
const dayStart = new Date("2026-11-09T00:00:00+08:00").getTime();
const dayEnd = dayStart + 864e5;
const base = path.join(os.homedir(), ".dsh", "sessions");
const files = [];
(function walk(p) {
  for (const e of fs.readdirSync(p, { withFileTypes: true })) {
    const fp = path.join(p, e.name);
    if (e.isDirectory()) walk(fp);
    else if (/\.jsonl\.zstd$/.test(e.name)) {
      const st = fs.statSync(fp);
      if (st.mtimeMs >= dayStart && st.mtimeMs < dayEnd) files.push(fp);
    }
  }
})(base);

const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
function dec(buf) {
  const idx = [];
  for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idx.push(i);
  if (idx.length <= 1) { try { return zlib.zstdDecompressSync(buf).toString("utf8"); } catch { return buf.toString("utf8"); } }
  let o = "";
  for (let k = 0; k < idx.length; k++) {
    const s = idx[k], e = k + 1 < idx.length ? idx[k + 1] : buf.length;
    try { o += zlib.zstdDecompressSync(buf.subarray(s, e)).toString("utf8"); } catch {}
  }
  return o;
}
function bj(ts) { return new Date(ts + TZ).toISOString().slice(11, 16); }
function tsOf(e) { const v = e.time || e.ts || (e.data && e.data.time); return typeof v === "number" ? v : null; }

let totalTurns = 0, errorTurns = 0;
const byHour = {}, byMsg = {}, bySession = {}, retryNear = { withRetry: 0, without: 0 };
const samples = [];

for (const fp of files) {
  const sid = path.basename(path.dirname(fp)).replace(/^session-/, "").slice(0, 8);
  const evs = dec(fs.readFileSync(fp)).split("\n").filter(Boolean).flatMap(l => { try { return [JSON.parse(l)]; } catch { return []; } });
  let model = "?", provider = "?";
  for (const e of evs) {
    if (e.type === "request/header") {
      const c = (e.data && e.data.header && e.data.header.config) || {};
      if (model === "?" && c.model) model = c.model;
      if (provider === "?" && c.provider) provider = c.provider;
    }
  }
  const turns = evs.filter(e => e.type === "turn/end");
  const retryTurns = new Set(evs.filter(e => /llm\/(retry|error|failure)/.test(e.type || "")).map(e => e.turn || (e.data && e.data.turn)));
  const errs = [];
  for (const e of turns) {
    const r = e.data && e.data.reason;
    if (!r || r.kind !== "error") continue;
    const msg = String((r.error && r.error.message) || (r.failure && r.failure.message) || r.message || "");
    const code = String((r.error && r.error.code) || (r.failure && r.failure.code) || r.code || "");
    const t = tsOf(e);
    const h = t ? bj(t).slice(0, 2) : "--";
    errs.push({ turn: e.turn || (e.data && e.data.turn), h, msg, code });
    if (samples.length < 4) samples.push({ sid, type: "turn/end", raw: JSON.stringify(e).slice(0, 700) });
  }
  totalTurns += turns.length;
  errorTurns += errs.length;
  for (const x of errs) {
    byHour[x.h] = (byHour[x.h] || 0) + 1;
    const k = x.code + " | " + x.msg.slice(0, 90);
    byMsg[k] = (byMsg[k] || 0) + 1;
    if (retryTurns.has(x.turn)) retryNear.withRetry++; else retryNear.without++;
  }
  if (errs.length) bySession[sid] = { model: provider + "/" + model, turns: turns.length, errors: errs.length, detail: errs.map(x => "T" + x.turn + "@" + x.h).join(" ") };
}

console.log("=== 今日真实 provider 生成失败（turn/end reason.kind=error）===");
console.log("会话文件 " + files.length + "，turn/end 总数 " + totalTurns + "，失败轮 " + errorTurns +
  "（" + (totalTurns ? (errorTurns / totalTurns * 100).toFixed(1) : "0") + "%）");

console.log("\n=== 失败按北京时间(小时) ===");
Object.entries(byHour).sort().forEach(([h, v]) => console.log(h + "时 " + v));

console.log("\n=== 错误码 / 消息 ===");
Object.entries(byMsg).sort((a, b) => b[1] - a[1]).forEach(([k, v]) => console.log(String(v).padStart(3), k));

console.log("\n=== 按会话 ===");
Object.entries(bySession).sort((a, b) => b[1].errors - a[1].errors).forEach(([sid, v]) =>
  console.log(sid, v.model, "turns=" + v.turns, "errors=" + v.errors, v.detail));

console.log("\n=== 是否伴随 llm/retry ===");
console.log("同 turn 有 retry 事件: " + retryNear.withRetry + "，无: " + retryNear.without);

console.log("\n=== turn/end 原始样本 ===");
samples.forEach(s => console.log(s.sid, s.raw));

